class Solution {
    public long countGood(int[] nums,int k){
        Map<Integer,Integer> frequency=new HashMap<>();
        long pairs=0,answer=0;
        int left=0;
        for(int right=0;right<nums.length;right++){
            int value=nums[right],count=frequency.getOrDefault(value,0);
            pairs+=count;
            frequency.put(value,count+1);
            while(pairs>=k){
                answer+=nums.length-right;
                int removed=nums[left++],remaining=frequency.get(removed)-1;
                frequency.put(removed,remaining);
                pairs-=remaining;
            }
        }
        return answer;
    }
}

